META={'id':'g8-ma-kx-c','subj':'數學','name':'八上 數學 康軒 C卷','source':'康軒版 新挑戰 八年級數學（三）C卷（114上，教用版答案與解析；僅收選擇題）'}

sec('第1回 1-1 乘法公式')
ch('下列運算過程何者正確？',[r'\((x+y)^2=x^2+y^2\)',r'\(x(x+y)=x^2+y\)',r'\((x-y)^2=x^2-2xy-y^2\)',r'\((x+y)(x-y)=x^2-y^2\)'],4,r'(A) \((x+y)^2=x^2+2xy+y^2\)；(B) \(x(x+y)=x^2+xy\)；(C) \((x-y)^2=x^2-2xy+y^2\)。')
ch(r'若 \(a+b=2\)，則 \((a+1)(b+1)-ab\) 的值為何？',['1','2','3','4'],3,r'\((a+1)(b+1)-ab=(ab+a+b+1)-ab=a+b+1=2+1=3\)。')
ch(r'計算 \(0.6\times37-0.4\times25-0.6\times25+0.4\times37\) 的結果與下列哪一個式子相等？',[r'\((0.6+0.4)\times(37+25)\)',r'\((0.6+0.4)\times(37-25)\)',r'\((0.6-0.4)\times(37+25)\)',r'\((0.6-0.4)\times(37-25)\)'],2,r'原式＝\(0.6\times(37-25)+0.4\times(37-25)=(0.6+0.4)\times(37-25)\)。')
ch(r'已知 \(a=43\dfrac{1}{2}\)，\(b=13\dfrac{1}{2}\)，則 \(a^2+b^2-2ab\) 的值為何？',['400','900','1600','2500'],2,r'\(a^2-2ab+b^2=(a-b)^2=\left(43\dfrac{1}{2}-13\dfrac{1}{2}\right)^2=30^2=900\)。')
ch(r'計算 \(1717^2-717^2\) 的結果為幾位數？',['7','8','9','10'],1,r'\(1717^2-717^2=(1717+717)\times(1717-717)=2434\times1000=2434000\)，所求為 7 位數。')
ch('如附圖，將一個正方形切割成四個長方形，各邊邊長如圖所示，則鋪色部分面積為何？',[r'\((b-a)^2\)',r'\(b(b-a)\)',r'\(b(b+a)\)',r'\((b-a)(b+a)\)'],4,r'所求＝大正方形面積－小正方形面積＝\((b-a+a)^2-a^2=b^2-a^2=(b-a)(b+a)\)。',img=(1,850,975,1000,1095))
ch(r'【素養】下面是大元、揚揚、小麗、樂樂四人分別求 \(6.9^2\) 的值之部分過程：大元：\(6.9^2=6^2+0.9^2\)；揚揚：\(6.9^2=(6+0.9)^2=6^2+2\times6\times0.9+0.9^2\)；小麗：\(6.9^2=7^2-0.1^2\)；樂樂：\(6.9^2=(7-0.1)^2=7^2-2\times7\times0.1-0.1^2\)。設四人接下來皆無其他計算錯誤，則哪一人最後得到的答案是正確的？',['大元','揚揚','小麗','樂樂'],2,r'\(6.9^2=(6+0.9)^2=6^2+2\times6\times0.9+0.9^2\)；\(6.9^2=(7-0.1)^2=7^2-2\times7\times0.1+0.1^2\)，故只有揚揚正確。',img=(1,150,1125,550,1305))
ch(r'若 \(p=80^2-8^2\)，\(q=50^2+100\times30+30^2\)，\(r=80\times(55+26)\)，則 \(p\)、\(q\)、\(r\) 三數的大小關係為何？',[r'\(p>q>r\)',r'\(q>p>r\)',r'\(q>r>p\)',r'\(r>q>p\)'],4,r'\(p=80^2-8^2\)，\(q=50^2+2\times50\times30+30^2=(50+30)^2=80^2\)，\(r=80\times(55+26)=80\times81\)，\(\therefore r>q>p\)。')
ch(r'計算 \(143\times43\times\left(\dfrac{143}{43}-\dfrac{43}{143}\right)\) 的值為何？',['18600','18800','19600','19800'],1,r'原式＝\(143^2-43^2=(143+43)(143-43)=186\times100=18600\)。')
ch(r'【進階】若 \(24\dfrac{3}{8}\times25\dfrac{5}{8}=25^2-\square^2\)，\(66^2-\triangle\times66+6^2=60^2\)，且 \(\square\)、\(\triangle\) 皆為正數，則 \(\square\times\triangle=\)？',[r'\(\dfrac{9}{2}\)','3',r'\(\dfrac{15}{2}\)','5'],3,r'\(24\dfrac{3}{8}\times25\dfrac{5}{8}=\left(25-\dfrac{5}{8}\right)\times\left(25+\dfrac{5}{8}\right)=25^2-\left(\dfrac{5}{8}\right)^2\Rightarrow\square=\dfrac{5}{8}\)；\(66^2-2\times66\times6+6^2=(66-6)^2=60^2\Rightarrow\triangle=2\times6=12\)，\(\therefore\square\times\triangle=\dfrac{5}{8}\times12=\dfrac{15}{2}\)。')
endp()

sec('第2回 1-2 多項式與其加減運算')
ch(r'下列何者不是 \(x\) 的多項式？',['2016',r'\(-\dfrac{x^3}{3}\)',r'\(8x^2+2x+9\)',r'\(6x-2=5\)'],4,r'(D) 為一元一次方程式。')
ch('下列哪一個多項式的常數項最小？',[r'\(x^2-4x-6\)',r'\(2x^2+x\)',r'\(3x^2+7\)',r'\(5x-1\)'],1,r'各選項的常數項分別如下：(A) －6；(B) 0；(C) 7；(D) －1，故選(A)。')
ch(r'下列何者是 \(4x^3\) 的同類項？',[r'\(4x\)',r'\(-4x\)',r'\(-\dfrac{1}{4}x^3\)',r'\(3x^4\)'],3,r'與 \(4x^3\) 的次數相同者為同類項，故選(C)。')
ch(r'將多項式 \(5x-2+9x^2-3x+11+8x^2\) 中的同類項合併，可得 \(x\) 的一次項係數為何？',['2','8','9','13'],1,r'原式＝\((9x^2+8x^2)+(5x-3x)+(-2+11)=17x^2+2x+9\)，\(\therefore x\) 項係數為 2。')
ch(r'\(x\) 的二次多項式加 \(x\) 的三次多項式後，最多有幾項？',['3','4','5','6'],2,r'相加後為三次多項式，最多有 \(x^3\) 項、\(x^2\) 項、\(x\) 項和常數項，共 4 項。')
ch(r'俊傑化簡 \((x^2-5x+1)-(2-3x^2+x)\) 的過程如下，請問他從哪一個步驟開始出現錯誤？步驟一：原式＝\(x^2-5x+1-2+3x^2-x\)；步驟二：\(=x^2+3x^2-5x-x+1-2\)；步驟三：\(=(1+3)x^2-(5-1)x+(1-2)\)；步驟四：\(=4x^2-4x-1\)',['步驟一','步驟二','步驟三','步驟四'],3,r'步驟三中的 \((5-1)x\) 應為 \((5+1)x\)。')
ch(r'若兩多項式 \((m-2)x^2-4x+3\) 與 \(3-x^2+2nx\) 相等，則 \(m+n=\)？',['－3','－1','1','3'],2,r'\(m-2=-1\)，\(2n=-4\Rightarrow m=1\)，\(n=-2\)，\(\therefore m+n=1+(-2)=-1\)。')
ch(r'【進階】已知一長方形的周長為 \(2x^2-2x+6\)，且其中一邊長為 \(4x+1\)，則另一邊長為何？',[r'\(x^2+3x+4\)',r'\(x^2-5x+2\)',r'\(2x^2+2x+7\)',r'\(2x^2-6x+5\)'],2,r'所求＝\(\dfrac{1}{2}(2x^2-2x+6)-(4x+1)=x^2-x+3-4x-1=x^2-5x+2\)。')
ch(r'已知 \(-x^2+3x-1\) 減去多項式 \(A\)，再加上 \(-3x^2+x+4\)，結果為 \(3x-1\)，則多項式 \(A=\)？',[r'\(2x^2-x-4\)',r'\(2x^2+5x-6\)',r'\(-4x^2+x+4\)',r'\(-4x^2+7x+2\)'],3,r'\((-x^2+3x-1)-A+(-3x^2+x+4)=3x-1\)，\(A=(-x^2+3x-1)+(-3x^2+x+4)-(3x-1)=-4x^2+x+4\)。')
ch(r'將兩多項式以直式做加法的過程如下：\((ax^2-x+9)+(3x^2-bx-14)=x^2+2x-c\)，假設過程中沒有計算錯誤，則 \(a\)、\(b\)、\(c\) 三數的大小關係為何？',[r'\(a>b>c\)',r'\(b>a>c\)',r'\(b>c>a\)',r'\(c>a>b\)'],4,r'由上式知：\(a+3=1\Rightarrow a=-2\)；\(-1+(-b)=2\Rightarrow b=-3\)；\(9+(-14)=-c\Rightarrow c=5\)，\(\therefore c>a>b\)。',img=(3,868,1435,1000,1520))
endp()

sec('第3回 1-3 多項式的乘除運算')
ch(r'計算 \(6x^2\div3x^2\cdot(-2x)=\)？',[r'\(-4x\)',r'\(-4x^2\)',r'\(4x\)',r'\(4x^2\)'],1,r'原式＝\(2\cdot(-2x)=-4x\)。')
ch(r'若 \((x-3)(x+4)-(x-1)(x+2)=ax^2+bx+c\)，則 \(a+b+c=\)？',['－12','－10','10','12'],2,r'\((x-3)(x+4)-(x-1)(x+2)=(x^2+x-12)-(x^2+x-2)=-10\Rightarrow a=0\)，\(b=0\)，\(c=-10\)，\(a+b+c=-10\)。')
ch(r'有一多項式與 \(2x+3\) 的乘積為 \(6x^2-11x-30\)，則此多項式為何？',[r'\(3x-5\)',r'\(3x-6\)',r'\(3x-10\)',r'\(3x-15\)'],3,r'\((6x^2-11x-30)\div(2x+3)=3x-10\)。')
ch(r'已知 \(A\) 為 \(x\) 的多項式，則下列何者不可能為 \(A\) 除以 \(10x^2+21x-10\) 的餘式？',['0',r'\(\dfrac{1}{2}\)',r'\(2x+5\)',r'\(2x^2+5\)'],4,r'餘式的次數必小於除式的次數，故不可能為(D)。')
ch(r'若多項式 \(A\) 除以 \(4x-1\) 後，得商式為 \(x+\dfrac{1}{2}\)，餘式為 \(\dfrac{1}{2}\)，則多項式 \(A\) 為何？',[r'\(4x^2+x\)',r'\(4x^2-x\)',r'\(4x^2+x-1\)',r'\(4x^2-x-1\)'],1,r'\(A=(4x-1)\left(x+\dfrac{1}{2}\right)+\dfrac{1}{2}=4x^2+2x-x-\dfrac{1}{2}+\dfrac{1}{2}=4x^2+x\)。')
ch(r'已知 \(6x^2+19x+13\) 除以另一個多項式 \(A\) 後，得到商式為 \(2x+3\)，餘式為 \(-2\)，則多項式 \(A\) 為何？',[r'\(3x+3\)',r'\(3x+5\)',r'\(3x-3\)',r'\(3x-5\)'],2,r'\(A=[(6x^2+19x+13)-(-2)]\div(2x+3)=(6x^2+19x+15)\div(2x+3)=3x+5\)。')
ch(r'【進階】附圖是亭如計算多項式除法的過程：\((6x^2+ax+d)\div(bx-1)\)，商式 \(3x+f\)，其中第一次相減列 \(6x^2+cx\)，餘下 \(-4x+d\)，第二次相減列 \(ex+2\)，最後餘式為 3。則下列敘述何者正確？',[r'\(a>c\)',r'\(e=4\)',r'\(c+f=d\)',r'\(b+f=0\)'],4,r'\(3b=6\Rightarrow b=2\)；\(c=3\times(-1)=-3\)；\(a-c=-4\Rightarrow a=c-4=-7\)；\(e=-4\)；\(f=(-4)\div2=-2\)；\(d-2=3\Rightarrow d=5\)，故選(D)。',img=(5,828,1060,1000,1220))
ch(r'若 \(3x^2-ax+6\) 可被 \(x+2\) 整除，則 \(a=\)？',['－10','－9','－6','－3'],2,r'\((3x^2-ax+6)\div(x+2)\) 的商式為 \(3x+(-a-6)\)，餘式為 \(6-2(-a-6)=2a+18\)，令 \(2a+18=0\Rightarrow a=-9\)。')
ch('【素養】如附圖，小輝、阿田、大軍、晴晴四人分別有一張長方形色紙，若他們四人的色紙恰可拼成一個大長方形，則所拼成的大長方形面積為何？',[r'\(2x^2-4x-6\)',r'\(2x^2+4x-6\)',r'\(2x^2+15x+18\)',r'\(2x^2+15x-8\)'],3,r'可拼成大長方形如右：面積＝\([(2x-1)+4](6+x)=(2x+3)(6+x)=2x^2+15x+18\)。',img=(5,720,1300,1000,1395))
ch(r'【進階】將 \(3002\times3005-3001\times3006\) 中的 3000 均以 \(x\) 表示，例如 \(3002=x+2\)，則由此方式可求得算式 \(3002\times3005-3001\times3006\) 之值為何？',['4','14','24','34'],1,r'\(3002\times3005-3001\times3006=(x+2)(x+5)-(x+1)(x+6)=(x^2+7x+10)-(x^2+7x+6)=4\)。')
endp()

sec('第4回 2-1 平方根與近似值')
ch('下列哪一個數是完全平方數？',['4','0.4','0.04',r'\(\dfrac{1}{4}\)'],1,r'可以寫成另一個整數的平方的正整數即為完全平方數，故選(A)。')
ch('下列關於平方根的敘述，何者正確？',[r'因為 \(a=(-23)^2\)，所以 \(a\) 是 \(-23\) 的平方根',r'因為 \(-16=-4^2\)，所以 \(-4\) 是 \(-16\) 的平方根','因為找不到任何一個整數、分數或小數的平方等於 29.3，所以 29.3 沒有平方根',r'若 \(a\) 是 30 的平方根，則 \(-a\) 也是 30 的平方根'],4,r'(A) \(-23\) 是 \(a\) 的平方根，\(a\) 是 \(-23\) 的平方；(B) \(-16\) 沒有平方根，\(-4\) 是 16 的平方根；(C) 29.3 的平方根為 \(\pm\sqrt{29.3}\)。')
ch('下列哪一個整數最接近 829 的正平方根？',['28','29','30','90'],2,r'\(28^2=784\)，\(29^2=841\)，\(28.5^2=812.25\)，\(\therefore29\) 最接近 829 的正平方根。')
ch(r'將 \(\sqrt{3}\)、\(\sqrt{4}\)、\(\sqrt{8}\)、\(\sqrt{11}\)、\(\sqrt{13}\)、\(\sqrt{15}\)、\(\sqrt{17}\)、\(\sqrt{19}\)、\(\sqrt{21}\) 共 9 個數，逐一以點標示在附圖的數線上（\(A\)、\(B\) 分別對應 3、4），則會有幾個點位於 \(A\)、\(B\) 之間？',['2','3','4','5'],2,r'找大於 \(\sqrt{9}\)、小於 \(\sqrt{16}\) 的數，共有 \(\sqrt{11}\)、\(\sqrt{13}\)、\(\sqrt{15}\) 這 3 個點。',img=(7,815,758,980,805))
ch(r'已知 \(a\) 為整數，且 \(a<\sqrt{250}<a+1\)，則 \(a=\)？',['13','14','15','16'],3,r'\(15^2<250<16^2\Rightarrow15<\sqrt{250}<16\)，\(\therefore a=15\)。')
ch(r'已知 \(x=\dfrac{1}{9}+\dfrac{1}{16}\)，則 \(x\) 的正平方根為何？',[r'\(\dfrac{1}{12}\)',r'\(\dfrac{1}{4}\)',r'\(\dfrac{5}{12}\)',r'\(\dfrac{7}{12}\)'],3,r'\(x=\dfrac{1}{9}+\dfrac{1}{16}=\dfrac{16+9}{144}=\dfrac{25}{144}\)，\(\therefore\) 所求＝\(\sqrt{x}=\sqrt{\dfrac{25}{144}}=\dfrac{5}{12}\)。')
ch('【素養】圖(一)是 5 個邊長為 1 的小正方形所拼成的長方形，將圖(一)沿虛線剪下，拼成一個大正方形，如圖(二)所示，則此大正方形的邊長為何？',[r'\(\sqrt{2}\)',r'\(\sqrt{3}\)',r'\(\sqrt{5}\)',r'\(\sqrt{6}\)'],3,r'正方形面積為 5，邊長為 \(\sqrt{5}\)。',img=(7,755,1105,985,1190))
ch(r'若 \(a\) 為 36 的平方根，\(b\) 為 16 的平方根，則 \(a+b\) 不可能為下列哪一個數？',['－10','－2','2','4'],4,r'\(a=\pm\sqrt{36}=\pm6\)，\(b=\pm\sqrt{16}=\pm4\Rightarrow a+b=10\) 或 2 或 －2 或 －10，故選(D)。')
ch(r'【進階】已知 \(a\) 為正整數，且 \(a<200\)，若 \(\sqrt{a}\) 也是整數，則滿足條件的 \(a\) 共有多少個？',['10','14','15','20'],2,r'\(14^2=196\)，\(15^2=225\)，\(\therefore a=1^2\)、\(2^2\)、……、\(13^2\)、\(14^2\)，共 14 個。')
ch(r'【進階】若 \(\sqrt{k}=156\)，且 \(k\) 的標準分解式為 \(2^a\times3^b\times13^c\)，則 \(a+b+c=\)？',['8','10','12','14'],1,r'\(\sqrt{k}=156=2^2\times3\times13\)，\(k=156^2=2^4\times3^2\times13^2\)，\(a+b+c=4+2+2=8\)。')
endp()

sec('第5回 複習一（1-1～2-1）')
ch(r'關於多項式 \(5x^3-2x+4-2x^4\) 的敘述，下列哪一個是正確的？',['是三次多項式',r'\(x\) 項係數為 2','常數項為 4',r'\(x^2\) 項係數為 \(-2\)'],3,r'(A) 四次；(B) \(x\) 項係數為 \(-2\)；(D) \(x^2\) 項係數為 0。')
ch(r'利用分配律展開 \((a-b)(c-d)\) 的結果為何？',[r'\(ac+bc-ad-bd\)',r'\(ac-bc+ad-bd\)',r'\(ac-bc-ad+bd\)',r'\(ac-bc-ad-bd\)'],3,r'\((a-b)(c-d)=ac-ad-bc+bd=ac-bc-ad+bd\)。')
ch(r'下列各項敘述，哪些是正確的？甲：\(2\dfrac{1}{4}\) 的平方根為 \(\pm\dfrac{3}{2}\)；乙：\(\sqrt{(-25)^2}=25\)；丙：\(\sqrt{16}\) 的平方根為 \(\pm4\)；丁：\(\sqrt{2^4\times3^6}=2^2\times3^4\)',['甲','甲、乙','甲、乙、丙','甲、乙、丁'],2,r'丙：\(\sqrt{16}=4\)，4 的平方根為 \(\pm2\)；丁：\(\sqrt{2^4\times3^6}=\sqrt{(2^2\times3^3)^2}=2^2\times3^3\)。')
ch(r'若 \((4-5x^2+3x)-A=-3x+1-8x^2\)，則 \(A=\)？',[r'\(-3x^2-3\)',r'\(-3x^2+3\)',r'\(3x^2+6x-3\)',r'\(3x^2+6x+3\)'],4,r'\(A=(4-5x^2+3x)-(-3x+1-8x^2)=3x^2+6x+3\)。')
ch(r'\((2x-1)(-x^2+3x+6)\) 乘開後的 \(x\) 項係數為何？',['3','6','9','12'],3,r'所求＝\(2\times6-1\times3=12-3=9\)。')
ch('附圖中的每一個角都是直角，則依圖中的數據，求此圖形的周長為何？',[r'\(10x+10\)',r'\(10x+12\)',r'\(12x+10\)',r'\(12x+12\)'],2,r'周長＝\(2[x+(x-1)+2x]+2[5+(x+2)]=2(4x-1)+2(x+7)=8x-2+2x+14=10x+12\)。',img=(9,830,955,1000,1062))
ch(r'已知正方形 \(ABCD\) 的面積為 360，則 \(\overline{AB}\) 的長度介於下列哪兩個數之間？',['17、18','18、19','19、20','20、21'],2,r'\(18^2=324\)，\(19^2=361\Rightarrow324<360<361\Rightarrow18<\sqrt{360}<19\)，即 \(18<\overline{AB}<19\)。')
ch(r'計算 \(\dfrac{125^2-25^2}{150}\) 之值為何？',['100','125','150','175'],1,r'原式＝\(\dfrac{(125+25)\times(125-25)}{150}=\dfrac{150\times100}{150}=100\)。')
ch(r'【進階】若 \(-3x^2+ax+1\) 除以 \(-x+2\) 得到餘式 \(-5\)，則 \(a=\)？',['－3','－2','2','3'],4,r'\((-3x^2+ax+1)-(-5)=-3x^2+ax+6\) 能被 \(-x+2\) 整除，商式為 \(3x+3\)，可得 \(a-6=-3\Rightarrow a=3\)。')
ch(r'【素養】附圖是桐桐、菲菲兩人關於一多項式乘法題目 \((\square x+5)(4x-1)\) 的對話。桐桐：\(x\) 項係數被桌球拍遮住了！菲菲：沒關係！我知道乘積展開後的各項係數總和是 21 喔！根據其內容，則桌球拍遮住的數為何？',['2','3','4','5'],1,r'設被遮住的數為 \(m\)，則 \((mx+5)(4x-1)=4mx^2+(-m+20)x-5\)，\(4m+(-m+20)+(-5)=21\Rightarrow3m=6\)，\(\therefore m=2\)。',img=(9,665,1410,1000,1570))
endp()

sec('第6回 2-2 根式的運算')
ch('下列何者是最簡根式？',[r'\(\sqrt{135}\)',r'\(\sqrt{153}\)',r'\(\sqrt{35}\)',r'\(\sqrt{175}\)'],3,r'(A) \(\sqrt{135}=3\sqrt{15}\)；(B) \(\sqrt{153}=3\sqrt{17}\)；(D) \(\sqrt{175}=5\sqrt{7}\)。')
ch('下列哪一個算式是錯誤的？',[r'\(\sqrt{3}+\sqrt{3}=\sqrt{6}\)',r'\(\sqrt{3}-\sqrt{3}=0\)',r'\(\sqrt{6}\times\sqrt{2}=\sqrt{12}\)',r'\(\sqrt{6}\div\sqrt{2}=\sqrt{3}\)'],1,r'(A) \(\sqrt{3}+\sqrt{3}=2\sqrt{3}\)。')
ch(r'算式 \((3\sqrt{2}+\sqrt{3})\times(3\sqrt{2}-\sqrt{3})\) 之值為何？',['9','15','21','27'],2,r'原式＝\((3\sqrt{2})^2-(\sqrt{3})^2=18-3=15\)。')
ch(r'若 \(\sqrt{6}\times\sqrt{m}=3\sqrt{14}\)，則 \(m=\)？',['14','21','28','35'],2,r'\(\sqrt{m}=\dfrac{3\sqrt{14}}{\sqrt{6}}=\dfrac{3\sqrt{7}}{\sqrt{3}}=\sqrt{21}\)，\(m=21\)。')
ch(r'若 \(a=\sqrt{3}+\sqrt{27}\)，\(b=\sqrt{108}\)，則 \(b\) 是 \(a\) 的幾倍？',[r'\(\dfrac{3}{2}\)',r'\(\dfrac{2}{3}\)',r'\(\dfrac{1}{2}\)','2'],1,r'\(a=\sqrt{3}+3\sqrt{3}=4\sqrt{3}\)，\(b=\sqrt{108}=6\sqrt{3}\)，所求＝\(\dfrac{b}{a}=\dfrac{6\sqrt{3}}{4\sqrt{3}}=\dfrac{3}{2}\)（倍）。')
ch(r'已知一三角形的面積為 \(5\sqrt{7}\)，底邊長為 \(\sqrt{2}\)，則底邊上的高為多少？',[r'\(3\sqrt{7}\)',r'\(6\sqrt{7}\)',r'\(2\sqrt{14}\)',r'\(5\sqrt{14}\)'],4,r'高＝\(\dfrac{2\times5\sqrt{7}}{\sqrt{2}}=\dfrac{10\sqrt{14}}{2}=5\sqrt{14}\)。')
ch(r'已知 \(x\) 為正數，且 \(6:x=x:12\)，則 \(x=\)？',[r'\(4\sqrt{3}\)',r'\(4\sqrt{6}\)',r'\(6\sqrt{2}\)',r'\(6\sqrt{3}\)'],3,r'\(x^2=6\times12=72\)，\(x=\pm\sqrt{72}=\pm6\sqrt{2}\)（負不合）。')
ch(r'將 \(\dfrac{\sqrt{3}+1}{\sqrt{3}-1}-\dfrac{\sqrt{3}-1}{\sqrt{3}+1}\) 化為最簡根式的結果為 \(a+b\sqrt{3}\)，其中 \(a\)、\(b\) 為整數，則 \(a+b=\)？',['－2','－1','1','2'],4,r'原式＝\(\dfrac{(\sqrt{3}+1)^2-(\sqrt{3}-1)^2}{(\sqrt{3}-1)(\sqrt{3}+1)}=\dfrac{4\sqrt{3}}{2}=2\sqrt{3}\Rightarrow a=0\)，\(b=2\Rightarrow a+b=2\)。')
ch(r'設 \(a=\sqrt{2}+\sqrt{6}\)，\(b=\sqrt{3}+\sqrt{5}\)，\(c=\sqrt{4}+\sqrt{4}\)，則 \(a\)、\(b\)、\(c\) 三數的大小關係為何？',[r'\(a>b>c\)',r'\(b>a>c\)',r'\(c>a>b\)',r'\(c>b>a\)'],4,r'\(a^2=(\sqrt{2}+\sqrt{6})^2=8+2\sqrt{12}\)，\(b^2=(\sqrt{3}+\sqrt{5})^2=8+2\sqrt{15}\)，\(c^2=(\sqrt{4}+\sqrt{4})^2=8+2\sqrt{16}\)，\(\because\sqrt{16}>\sqrt{15}>\sqrt{12}\)，\(\therefore c>b>a\)。')
ch(r'如附圖，長方形 \(ABCD\) 的面積為 120，且 \(\overline{AB}=4\sqrt{3}\)，則長方形 \(ABCD\) 的周長為何？',[r'\(24\sqrt{3}\)',r'\(26\sqrt{3}\)',r'\(28\sqrt{3}\)',r'\(30\sqrt{3}\)'],3,r'\(\overline{AD}=\dfrac{120}{4\sqrt{3}}=\dfrac{30}{\sqrt{3}}=10\sqrt{3}\)，周長＝\(2\times(4\sqrt{3}+10\sqrt{3})=28\sqrt{3}\)。',img=(11,855,1475,1003,1545))
endp()

sec('第7回 2-3 畢氏定理')
ch(r'\(\triangle ABC\) 中，若 \(\overline{AB}^2+\overline{AC}^2=\overline{BC}^2\)，則下列敘述何者正確？',[r'\(\angle C<90^\circ\)',r'\(\angle B=90^\circ\)',r'\(\angle C=90^\circ\)',r'\(\angle A<90^\circ\)'],1,r'\(\overline{AB}^2+\overline{AC}^2=\overline{BC}^2\Rightarrow\overline{BC}\) 為斜邊 \(\Rightarrow\angle A=90^\circ\Rightarrow\angle B<90^\circ\)，\(\angle C<90^\circ\)，故選(A)。')
ch('下列哪一組數據無法構成直角三角形的三邊長？',[r'1、\(\sqrt{2}\)、\(\sqrt{3}\)',r'\(3^2\)、\(4^2\)、\(5^2\)','8、15、17',r'\(\sqrt{6}\)、\(\sqrt{8}\)、\(\sqrt{14}\)'],2,r'(A) \(1^2+(\sqrt{2})^2=(\sqrt{3})^2\)；(B) \((3^2)^2+(4^2)^2=81+256=337\neq(5^2)^2=625\)；(C) \(8^2+15^2=17^2\)；(D) \((\sqrt{6})^2+(\sqrt{8})^2=(\sqrt{14})^2\)。')
ch(r'\(\triangle ABC\) 中，\(\angle B=90^\circ\)，以三邊為邊長分別向外作出正方形甲、乙、丙，如附圖所示。已知甲、乙的面積分別為 18 平方公分、24 平方公分，則丙的面積為多少平方公分？',['30','36','42','48'],3,r'\(\overline{AC}^2=\overline{AB}^2+\overline{BC}^2\Rightarrow\) 丙面積＝甲面積＋乙面積＝\(18+24=42\)（平方公分）。',img=(13,840,595,980,740))
ch(r'如附圖，等腰 \(\triangle ABC\) 中，\(\overline{AB}=\overline{AC}=10\)，\(\overline{BC}=16\)，則 \(\triangle ABC\) 的面積為何？',['32','36','40','48'],4,r'令 \(H\) 為 \(\overline{BC}\) 中點，連接 \(\overline{AH}\)，\(\overline{BH}=\dfrac{1}{2}\overline{BC}=8\)，\(\overline{AH}=\sqrt{10^2-8^2}=6\)，\(\triangle ABC\) 面積＝\(\dfrac{1}{2}\times16\times6=48\)。',img=(13,815,755,990,835))
ch(r'坐標平面上有四點 \(A(0,-2)\)、\(B(3,0)\)、\(C(-2,2)\)、\(D(1,-4)\)，則下列哪一線段最長？',[r'\(\overline{AB}\)',r'\(\overline{AC}\)',r'\(\overline{CD}\)',r'\(\overline{BD}\)'],3,r'\(\overline{AB}=\sqrt{13}\)，\(\overline{AC}=\sqrt{20}\)，\(\overline{CD}=\sqrt{3^2+(-6)^2}=\sqrt{45}\)，\(\overline{BD}=\sqrt{(-2)^2+(-4)^2}=\sqrt{20}\)，故選(C)。')
ch('已知一正方形的周長為 24，則其對角線的長度為何？',['6',r'\(4\sqrt{3}\)','8',r'\(6\sqrt{2}\)'],4,r'正方形邊長＝\(24\div4=6\)，所求＝\(\sqrt{6^2+6^2}=6\sqrt{2}\)。')
ch('【素養】小妍和小翊同時由學校出發，小妍先向東走 4 公里，再向北走 5 公里到達公園；而小翊先向西走 8 公里，再向南走 4 公里到達圖書館，則公園與圖書館兩地相距多少公里？',['15','17','20','26'],1,r'\(\sqrt{(8+4)^2+(5+4)^2}=\sqrt{12^2+9^2}=15\)（公里）。')
ch(r'【進階】附圖的 \(2\times2\) 方格中，共有 9 個點在格線的交點上。若每個方格的邊長都是 1，則方格中任意兩點間的距離不可能是下列哪一個選項？',[r'\(\sqrt{2}\)',r'\(\sqrt{3}\)',r'\(\sqrt{5}\)',r'\(2\sqrt{2}\)'],2,r'(A) \(\sqrt{2}=\sqrt{1^2+1^2}\)；(C) \(\sqrt{5}=\sqrt{1^2+2^2}\)；(D) \(2\sqrt{2}=\sqrt{8}=\sqrt{2^2+2^2}\)，故選(B)。',img=(13,875,1162,985,1252))
ch(r'如附圖，在長方形 \(ABCD\) 中，\(E\) 點在 \(\overline{AD}\) 上，且 \(\overline{BE}\perp\overline{CE}\)，若 \(\overline{BE}=6\)，\(\overline{CE}=8\)，則長方形 \(ABCD\) 的面積為何？',['36','40','45','48'],4,r'\(\overline{BC}=\sqrt{6^2+8^2}=10\)，\(\overline{AB}=\dfrac{6\times8}{10}=\dfrac{24}{5}\)，所求＝\(\overline{BC}\times\overline{AB}=10\times\dfrac{24}{5}=48\)。',img=(13,826,1290,990,1370))
ch('【進階】圓圓和小樂兩人同時同地出發，且分別向北和向東行走。已知圓圓每分鐘走 30 公尺，小樂每分鐘走 40 公尺，則半小時後兩人相距多少公尺？',['900','1200','1500','2100'],3,r'半小時＝30 分鐘，所求＝\(30\times\sqrt{30^2+40^2}=30\times50=1500\)（公尺）。')
endp()

sec('第8回 3-1 利用提公因式與乘法公式做因式分解')
ch('下列敘述何者錯誤？',[r'\(6x^2\) 是 \(-3x^2\) 的因式',r'\(-2\) 是 \(4x^2\) 的因式',r'\(x\) 是 \(x^2+1\) 的因式',r'\(-x\) 是 \(x^2+x\) 的因式'],3,r'(A) \((-3x^2)\div6x^2=-\dfrac{1}{2}\)；(B) \(4x^2\div(-2)=-2x^2\)；(C) \((x^2+1)\div x\) 得商式為 \(x\)，餘式為 1；(D) \((x^2+x)\div(-x)=-x-1\)，故選(C)。')
ch(r'下列何者為 \((x-2)^2\) 與 \((x-2)(x-3)\) 的公因式？',[r'\(x-2\)',r'\(x-3\)',r'\((x-2)^2\)',r'\((x-2)(x-3)\)'],1,r'\((x-2)^2\) 與 \((x-2)(x-3)\) 皆有因式 \(x-2\)，故 \(x-2\) 為其公因式。')
ch(r'若 \(x-1\) 與 \(x+3\) 都是 \(x^2+ax+b\) 的因式，則 \(a+b=\)？',['－3','－1','1','3'],2,r'\((x-1)(x+3)=x^2+2x-3\Rightarrow a=2\)，\(b=-3\Rightarrow a+b=-1\)。')
ch(r'已知多項式 \(A=(x+1)(3-x)\)、\(B=(x+2)(x-9)\)、\(C=3x^2-9x\)，則下列選項的多項式中，何者有一次公因式？',[r'\(A\)、\(B\)',r'\(B\)、\(C\)',r'\(A\)、\(C\)','以上皆無'],3,r'\(A=(x+1)(3-x)=-(x+1)(x-3)\)，\(C=3x^2-9x=3x(x-3)\)，因此 \(A\)、\(C\) 有公因式 \((x-3)\)。')
ch(r'下列何者為 \((x-3)(2x-1)-(3-x)(3x+2)\) 的因式？',[r'\(5x-1\)',r'\(5x+1\)',r'\(x-1\)',r'\(x+3\)'],2,r'原式＝\((x-3)(2x-1)+(x-3)(3x+2)=(x-3)[(2x-1)+(3x+2)]=(x-3)(5x+1)\)。')
ch('下列因式分解的結果，何者正確？',[r'\(25x^2+16=(5x+4)^2\)',r'\(4x^2-9=(4x+3)(4x-3)\)',r'\(49x^2-14x+4=(7x-2)^2\)',r'\(3x^2-108=3(x+6)(x-6)\)'],4,r'(A) \((5x+4)^2=25x^2+40x+16\)；(B) \(4x^2-9=(2x+3)(2x-3)\)；(C) \((7x-2)^2=49x^2-28x+4\)。')
ch(r'【素養】以下為小恩、婷婷兩人因式分解 \(\dfrac{1}{9}x^2-2x+9\) 的過程：小恩：原式＝\(\left(\dfrac{1}{3}x\right)^2-2\cdot\dfrac{1}{3}x\cdot3+3^2=\left(\dfrac{1}{3}x-3\right)^2\)；婷婷：原式＝\(\dfrac{1}{9}(x^2-18x+81)=\dfrac{1}{9}(x^2-2\cdot x\cdot9+9^2)=\dfrac{1}{9}(x-9)^2\)。則下列敘述何者正確？',['小恩正確，婷婷錯誤','小恩錯誤，婷婷正確','兩人皆正確','兩人皆錯誤'],3,r'小恩、婷婷皆正確。')
ch(r'【進階】已知某三角形的底和此底邊上的高皆為 \(ax+b\)，且 \(a\)、\(b\) 均為正整數。若此三角形的面積為 \(\dfrac{9}{2}x^2+6x+2\)，則 \(a+b=\)？',['4','5','6','7'],2,r'\(2\left(\dfrac{9}{2}x^2+6x+2\right)=9x^2+12x+4=(3x+2)^2=(ax+b)^2\)，\(\therefore a=3\)，\(b=2\)，\(a+b=3+2=5\)。')
ch(r'如附圖，正方形 \(ABCD\) 的邊長為 \(3x\)，若剪去一個邊長為 2 的正方形，則剩餘的面積與下列哪一個長方形的面積相等？',[r'長 \(3x+2\)、寬 \(3x-2\)',r'長 \(3x+2\)、寬 \(x\)',r'長 3、寬 \(2x\)',r'長 \(3+2x\)、寬 \(3-2x\)'],1,r'\((3x)^2-2^2=(3x+2)(3x-2)\)。',img=(15,850,1418,985,1545))
ch(r'【進階】已知多項式 \(3x^2-kx+1\) 為 \(x+1\) 的倍式，則 \(3x^2-kx+1\) 可因式分解為何？',[r'\((x+1)(3x+1)\)',r'\((x+1)(3x-1)\)',r'\(3(x+1)^2\)',r'\(3(x+1)(x-1)\)'],1,r'以長除法計算 \((3x^2-kx+1)\div(x+1)\)，商式為 \(3x+1\)，餘式為 0，\(\therefore3x^2-kx+1=(x+1)(3x+1)\)。')
endp()

sec('第9回 3-2 利用十字交乘法做因式分解')
ch(r'下列何者是 \(15x^2-22x+8\) 的因式？',[r'\(3x+2\)',r'\(5x-4\)',r'\(3x-4\)',r'\(x-2\)'],2,r'\(15x^2-22x+8=(5x-4)(3x-2)\)。')
ch('下列何者不能因式分解？',[r'\(4x^2-9\)',r'\(x^2+12x+36\)',r'\(x^2-10x-21\)',r'\(2x^2+9x-18\)'],3,r'(A) 原式＝\((2x+3)(2x-3)\)；(B) 原式＝\((x+6)^2\)；(D) 原式＝\((x+6)(2x-3)\)。')
ch(r'若 \(6x^2+x-2\) 可因式分解成 \((3x+a)(bx+c)\)，其中 \(a\)、\(b\)、\(c\) 均為整數，則 \(a+c=\)？',['1','2','3','4'],1,r'\(6x^2+x-2=(3x+2)(2x-1)=(3x+a)(bx+c)\)，\(\therefore a=2\)，\(b=2\)，\(c=-1\)，\(a+c=2+(-1)=1\)。')
ch(r'因式分解 \((x+1)(x-2)-4\) 的結果為何？',[r'\((x-1)(x+2)\)',r'\((x+1)(x-6)\)',r'\((x-3)(x+2)\)',r'\((x+3)(x-2)\)'],3,r'原式＝\(x^2-x-6=(x-3)(x+2)\)。')
ch(r'下列何者為 \(2x^2-x-1\) 與 \(6x^2+17x+7\) 的公因式？',[r'\(x-1\)',r'\(x+1\)',r'\(2x-1\)',r'\(2x+1\)'],4,r'\(2x^2-x-1=(x-1)(2x+1)\)，\(6x^2+17x+7=(2x+1)(3x+7)\)，\(\therefore\) 公因式為 \(2x+1\)。')
ch(r'若 \(2x+3\) 為 \(8x^2+10x+m\) 的因式，則因式分解 \(x^2-2x+m\) 的結果為何？',[r'\((x+1)(x-3)\)',r'\((x+2)(x-4)\)',r'\((x+3)(x-5)\)',r'\((x+4)(x-6)\)'],1,r'\((8x^2+10x+m)\div(2x+3)\) 的商式為 \(4x-1\)，餘式為 \(m+3\)，\(m+3=0\Rightarrow m=-3\)，\(\therefore x^2-2x-3=(x+1)(x-3)\)。')
ch(r'已知一梯形的面積為 \(3x^2+\dfrac{19}{2}x-18\)，若此梯形的上底為 \(x-4\)，下底為 \(2x\)，則其高為何？',[r'\(2x+4\)',r'\(2x+6\)',r'\(2x+8\)',r'\(2x+9\)'],4,r'\(2\left(3x^2+\dfrac{19}{2}x-18\right)=6x^2+19x-36=(2x+9)(3x-4)\)，又上底＋下底＝\(x-4+2x=3x-4\)，\(\therefore\) 高為 \(2x+9\)。')
ch(r'已知一長方形的面積為 \(2x^2+x-15\)，若它的長、寬均為 \(x\) 的一次多項式，且各項係數皆為整數，則此長方形的周長為何？',[r'\(6x-14\)',r'\(6x-4\)',r'\(6x+4\)',r'\(6x+14\)'],2,r'\(2x^2+x-15=(x+3)(2x-5)\)，\(\therefore\) 周長＝\(2[(x+3)+(2x-5)]=6x-4\)。')
ch(r'【進階】算式 \(2\times99^2+5\times99+3\) 之值為何？',['990','10390','19900','20100'],4,r'令 \(x=99\)，原式＝\(2x^2+5x+3=(x+1)(2x+3)\)，\(x=99\) 代回，得 \((99+1)(2\times99+3)=100\times201=20100\)。')
ch(r'【進階】若 \(x^2+x-k\) 可因式分解成兩個一次式的乘積，且 \(k\) 為整數，則 \(k\) 的值不可能為下列何者？',['2','6','10','12'],3,r'(A) \(x^2+x-2=(x-1)(x+2)\)；(B) \(x^2+x-6=(x-2)(x+3)\)；(D) \(x^2+x-12=(x-3)(x+4)\)，故選(C)。')
endp()

sec('第10回 複習二（2-2～3-2）')
ch('下列哪一個多項式不能因式分解成一個完全平方式？',[r'\(x^2+4x+4\)',r'\(x^2-4x+4\)',r'\(4x^2-4x-1\)',r'\(4x^2-4x+1\)'],3,r'(A) \(x^2+4x+4=(x+2)^2\)；(B) \(x^2-4x+4=(x-2)^2\)；(D) \(4x^2-4x+1=(2x-1)^2\)。')
ch(r'算式 \(\sqrt{3}\times(\sqrt{48}-\sqrt{27})\) 之值為何？',['3','4',r'\(3\sqrt{3}\)',r'\(4\sqrt{3}\)'],1,r'\(\sqrt{3}\times(\sqrt{48}-\sqrt{27})=\sqrt{3}\times(4\sqrt{3}-3\sqrt{3})=\sqrt{3}\times\sqrt{3}=3\)。')
ch(r'直角坐標平面上有 \(C(-1,3)\) 和 \(D(2,-1)\) 兩點，則 \(C\)、\(D\) 兩點的距離為何？',['3','4','5','7'],3,r'\(\overline{CD}=\sqrt{(-1-2)^2+[3-(-1)]^2}=\sqrt{(-3)^2+4^2}=5\)。')
ch(r'若 \(x^2+mx+n\) 可因式分解成 \((x+7)(x-3)\)，則下列何者正確？',[r'\(m=7+3\)',r'\(m=-7-3\)',r'\(n=7\times3\)',r'\(n=7\times(-3)\)'],4,r'\(m=7+(-3)\)，\(n=7\times(-3)\)，故選(D)。')
ch(r'已知 \(\triangle ABC\) 中，\(\angle A=90^\circ\)，若 \(\overline{AB}=8\)，\(\overline{AC}=15\)，則斜邊上的高為何？',[r'\(\dfrac{60}{17}\)',r'\(\dfrac{120}{17}\)',r'\(\dfrac{180}{17}\)',r'\(\dfrac{240}{17}\)'],2,r'\(\overline{BC}=\sqrt{8^2+15^2}=17\)，所求＝\(\dfrac{8\times15}{17}=\dfrac{120}{17}\)。')
ch(r'若因式分解 \(3x^2+14x-5\) 的結果為 \((ax+b)(x+5)\)，則 \(5a-b\) 的平方根為何？',[r'\(\pm3\)',r'\(\pm4\)',r'\(\pm5\)',r'\(\pm6\)'],2,r'\((3x^2+14x-5)\div(x+5)=3x-1\Rightarrow a=3\)，\(b=-1\)，\(5a-b=16\)，16 的平方根為 \(\pm4\)。')
ch(r'已知 \(a=\sqrt{7}+\sqrt{3}\)，\(b=\sqrt{7}-\sqrt{3}\)，則 \((a+b)^2-(a-b)^2=\)？',['8','10','14','16'],4,r'\((a+b)^2-(a-b)^2=4ab=4\times(\sqrt{7}+\sqrt{3})\times(\sqrt{7}-\sqrt{3})=4\times(7-3)=16\)。')
ch(r'如附圖，已知長方形 \(ABCD\) 的面積為 \(3(x+3)(x-4)-(x+3)(x-2)\)，且 \(\overline{CD}=x+3\)，則下列何者為 \(\overline{AD}\) 的長？',[r'\(2x-2\)',r'\(2x-6\)',r'\(2x-10\)',r'\(2x-14\)'],3,r'\(3(x+3)(x-4)-(x+3)(x-2)=(x+3)(3x-12-x+2)=(x+3)(2x-10)\)，所以 \(\overline{AD}=2x-10\)。',img=(19,840,1150,1000,1240))
ch(r'如附圖，有一長方形 \(ABCD\)，今以 \(\overline{AB}\)、\(\overline{AD}\) 為邊長分別作正方形甲、乙。若長方形 \(ABCD\) 的其中一條對角線長為 14，則正方形甲、乙的面積和為何？',['14','140','196','200'],3,r'所求＝\(\overline{AB}^2+\overline{AD}^2=\overline{BD}^2=14^2=196\)。',img=(19,870,1305,1000,1432))
ch(r'【進階】算式 \(8+\sqrt{52\square13}=10\) 中，在 \(\square\) 內應填入下列哪一種運算符號，才能使等式成立？',['＋','－','×','÷'],4,r'\(8+\sqrt{52\square13}=10\Rightarrow\sqrt{52\square13}=2\Rightarrow52\square13=4\)，\(\therefore\square\) 內應填入 ÷。')
endp()

sec('第11回 4-1 因式分解解一元二次方程式')
ch('下列何者化簡後為一元二次方程式？',[r'\(3x(x+1)\)',r'\(x^2+2x=x^2+2\)',r'\((x-1)^2=(x+1)^2\)',r'\((x-3)(2x+1)=x^2-x\)'],4,r'(A) 一元二次式；(B) \(2x-2=0\)，一元一次方程式；(C) \(-4x=0\)，一元一次方程式；(D) \(2x^2-5x-3=x^2-x\Rightarrow x^2-4x-3=0\)，一元二次方程式。')
ch(r'若方程式 \((x-2)(x+3)=0\)，則下列何者可能為 \(x-2\) 的值？',['－5','－2','2','5'],1,r'\((x-2)(x+3)=0\)，\(x=2\) 或 \(x=-3\)，\(\therefore x-2\) 的值為 0 或 \(-3-2=-5\)。')
ch(r'若 \(x=1\) 是一元二次方程式 \(x^2+ax-6=0\) 的解，則 \(a=\)？',['5','4','3','2'],1,r'\(x=1\) 代入方程式得 \(1^2+a\times1-6=0\Rightarrow a=5\)。')
ch(r'下列哪一個方程式與 \(2x^2-4x+6=0\) 有相同的解？',[r'\(x^2+2x+3=\dfrac{1}{2}\)',r'\(x^2+2x+3=0\)',r'\(x^2-2x+3=\dfrac{1}{2}\)',r'\(x^2-2x+3=0\)'],4,r'\(2x^2-4x+6=0\) 等號兩邊同除以 2 可得 \(x^2-2x+3=0\)，故選(D)。')
ch('下列哪一個方程式的兩根相等？',[r'\(x^2-9x=0\)',r'\(25x^2=81\)',r'\(x^2-6x+9=0\)',r'\(x^2+5x+4=0\)'],3,r'(A) 0 和 9；(B) \(\pm\dfrac{9}{5}\)；(C) 3（重根）；(D) \(-1\) 和 \(-4\)。')
ch(r'下列何者為 \(x^2-7x=-2x-4\) 的一解？',['－3','－2',r'\(\dfrac{1}{2}\)','1'],4,r'\(x^2-7x+2x+4=0\Rightarrow x^2-5x+4=0\Rightarrow(x-1)(x-4)=0\Rightarrow x=1\) 或 4。')
ch(r'若 \(a\) 是 \(2x^2+3x-5=0\) 的一根，則 \(8-3a-2a^2=\)？',['－13','－3','3','13'],3,r'\(2a^2+3a-5=0\)，\(2a^2+3a=5\)，\(8-3a-2a^2=8-(3a+2a^2)=8-5=3\)。')
ch(r'下列解一元二次方程式 \(2x^2+3x+1=x^2-1\) 的步驟中，哪一個步驟開始發生錯誤？',[r'步驟一：因式分解得 \((2x+1)(x+1)=(x+1)(x-1)\)',r'步驟二：同除以 \(x+1\) 得 \(2x+1=x-1\)',r'步驟三：移項得 \(2x-x=-1-1\)',r'步驟四：故得 \(x=-2\)'],2,r'\(\because\) 同除以 \((x+1)\) 會減根，\(\therefore\)(B)錯誤。')
ch(r'【進階】當 \(c\) 的值為下列何者時，可使方程式 \(x^2+cx-10=0\) 的兩根均為整數？',['－6','－2','3','10'],3,r'\(-10=1\times(-10)=2\times(-5)=5\times(-2)=10\times(-1)\)，(C) \(c=5+(-2)=3\)。')
ch(r'【素養】附圖是晴晴數學作業簿的其中一頁：「◎」是一種新的運算符號，定義為：\(a◎b=ab+b-1\)。(1) \(2◎3=2\times3+3-1=8\)；(2) \(2x◎(x+1)\)。若第(2)小題的值為 5，則 \(x=\)？',[r'1 或 \(\dfrac{5}{2}\)',r'1 或 \(-\dfrac{5}{2}\)',r'\(-1\) 或 \(\dfrac{5}{2}\)',r'\(-1\) 或 \(-\dfrac{5}{2}\)'],2,r'\(2x◎(x+1)=5\Rightarrow2x(x+1)+(x+1)-1=5\Rightarrow2x^2+3x-5=0\Rightarrow(x-1)(2x+5)=0\)，\(x=1\) 或 \(-\dfrac{5}{2}\)。',img=(21,755,1435,1000,1590))
endp()

sec('第12回 4-2 配方法與公式解')
ch('下列何者不能化成完全平方式？',[r'\(9x^2-6x+4\)',r'\(4x^2+20x+25\)',r'\(x^2-8x+16\)',r'\(16x^2+24x+9\)'],1,r'(B) 原式＝\((2x+5)^2\)；(C) 原式＝\((x-4)^2\)；(D) 原式＝\((4x+3)^2\)。')
ch(r'若 \((x+3)^2=5\)，則 \(x=\)？',[r'\(-2\) 或 8',r'\(-8\) 或 2',r'\(3\pm\sqrt{5}\)',r'\(-3\pm\sqrt{5}\)'],4,r'\((x+3)^2=5\Rightarrow x+3=\pm\sqrt{5}\Rightarrow x=-3\pm\sqrt{5}\)。')
ch(r'下列何者為方程式 \(x^2-6x+1=-2\) 的解？',[r'\(3\pm\sqrt{2}\)',r'\(-3\pm\sqrt{2}\)',r'\(3\pm\sqrt{6}\)',r'\(-3\pm\sqrt{6}\)'],3,r'\(x^2-6x+1=-2\)，\(x^2-6x+3=0\)，\(\therefore x=\dfrac{-(-6)\pm\sqrt{(-6)^2-4\times1\times3}}{2\times1}=\dfrac{6\pm\sqrt{24}}{2}=3\pm\sqrt{6}\)。')
ch('下列哪一個一元二次方程式有相異兩根？',[r'\(x^2-4x+4=0\)',r'\(x^2+x+2=0\)',r'\(x^2+2x-5=0\)',r'\(2x^2-x+3=0\)'],3,r'(A) \((-4)^2-4\times1\times4=0\)，有相等兩根；(B) \(1^2-4\times1\times2=-7<0\)，無解；(C) \(2^2-4\times1\times(-5)=24>0\)，有相異兩根；(D) \((-1)^2-4\times2\times3=-23<0\)，無解，故選(C)。')
ch(r'若一元二次方程式 \(2x^2+4x-5=0\) 可配方成 \((x+a)^2=b\) 的形式，則 \(a+b=\)？',[r'\(\dfrac{9}{2}\)',r'\(\dfrac{5}{2}\)','3','2'],1,r'\(2x^2+4x-5=0\Rightarrow x^2+2x=\dfrac{5}{2}\Rightarrow x^2+2x+1^2=\dfrac{5}{2}+1^2\Rightarrow(x+1)^2=\dfrac{7}{2}\Rightarrow a=1\)，\(b=\dfrac{7}{2}\)，\(a+b=\dfrac{9}{2}\)。')
ch(r'下面是小齊利用配方法解一元二次方程式 \(4x^2-3x-8=0\) 的過程：步驟一：\(x^2-\dfrac{3}{4}x=2\)；步驟二：\(x^2-\dfrac{3}{4}x+\left(\dfrac{3}{2}\right)^2=2+\left(\dfrac{3}{2}\right)^2\)；步驟三：\(\left(x-\dfrac{3}{2}\right)^2=\dfrac{17}{4}\)；步驟四：\(x-\dfrac{3}{2}=\pm\dfrac{\sqrt{17}}{2}\)，故 \(x=\dfrac{3\pm\sqrt{17}}{2}\)。請問小齊從哪一個步驟開始發生錯誤？',['步驟一','步驟二','步驟三','步驟四'],2,r'步驟二應為 \(x^2-\dfrac{3}{4}x+\left(\dfrac{3}{8}\right)^2=2+\left(\dfrac{3}{8}\right)^2\)。')
ch(r'若一元二次方程式 \(3x^2-6x+m=0\) 無解，則 \(m\) 的值不可能為下列何者？',['30','10','7','3'],4,r'\((-6)^2-4\times3\times m<0\Rightarrow36-12m<0\)，\(m>3\)，故選(D)。')
ch(r'解一元二次方程式 \(x^2+6x+a=0\)，得 \(x=-3\pm\sqrt{7}\)，則 \(a=\)？',['－2','2','－4','4'],2,r'\(x=-3\pm\sqrt{7}\Rightarrow x+3=\pm\sqrt{7}\Rightarrow(x+3)^2=(\pm\sqrt{7})^2\Rightarrow x^2+6x+2=0\)，\(\therefore a=2\)。')
ch(r'已知 \(x=3\) 是一元二次方程式 \(2(x-a)^2=18\) 的一個解，且 \(a>0\)，則 \(a=\)？',['2','3','6','9'],3,r'\(x=3\) 代入得 \(2(3-a)^2=18\)，\(3-a=\pm3\)，\(a=6\) 或 0（不合）。')
ch(r'【素養】下面是小哲、子涵兩人的對話：小哲：點 \((a,b)\) 在坐標平面上的第四象限；子涵：而且 \(a\)、\(b\) 都是方程式 \(x^2+3x-1=0\) 的解喔！根據上述對話，求 \(a=\)？',[r'\(\dfrac{-3-\sqrt{5}}{2}\)',r'\(\dfrac{-3+\sqrt{5}}{2}\)',r'\(\dfrac{-3-\sqrt{13}}{2}\)',r'\(\dfrac{-3+\sqrt{13}}{2}\)'],4,r'\(x^2+3x-1=0\)，\(x=\dfrac{-3\pm\sqrt{3^2-4\times1\times(-1)}}{2\times1}=\dfrac{-3\pm\sqrt{13}}{2}\)，又 \(a>0\)，\(b<0\)，\(\therefore a=\dfrac{-3+\sqrt{13}}{2}\)。')
endp()

sec('第13回 4-3 應用問題')
ch('已知小芳 4 年前年齡的平方恰好是他 2 年後的年齡，則小芳今年幾歲？',['5','7','9','16'],2,r'設小芳今年 \(x\) 歲，\((x-4)^2=x+2\Rightarrow x^2-9x+14=0\Rightarrow(x-7)(x-2)=0\)，\(x=7\) 或 2（不合）。')
ch('毛毛在老街販賣霜淇淋，已知當天賣出霜淇淋的數量是霜淇淋單價的 2 倍多 10，並獲得收入 1500 元，請問霜淇淋每個賣多少元？',['20','25','30','35'],2,r'設霜淇淋每個賣 \(x\) 元，共賣出 \((2x+10)\) 個，\(x(2x+10)=1500\Rightarrow x^2+5x-750=0\Rightarrow(x-25)(x+30)=0\)，即 \(x=25\) 或 \(x=-30\)（不合）。')
ch(r'已知三個連續奇數中最小的數為 \(x\)，且三數的平方和為 515，則依題意可列出的一元二次方程式為何？',[r'\(x^2+(x+1)^2+(x+2)^2=515\)',r'\(x^2+(x+1)^2+(x+3)^2=515\)',r'\(x^2+(x+2)^2+(x+4)^2=515\)',r'\((x+1)^2+(x+3)^2+(x+5)^2=515\)'],3,r'三個連續奇數為 \(x\)、\(x+2\)、\(x+4\)，\(x^2+(x+2)^2+(x+4)^2=515\)。')
ch('已知某正數比其倒數少 4，則此正數為何？',['1','2',r'\(2+\sqrt{5}\)',r'\(-2+\sqrt{5}\)'],4,r'設此正數為 \(x\)，\(x=\dfrac{1}{x}-4\Rightarrow x^2+4x-1=0\Rightarrow x=\dfrac{-4\pm\sqrt{20}}{2}=-2\pm\sqrt{5}\)（負不合）。')
ch('如附圖，將邊長為 20 公分的正方形，在四角截去四個相等的等腰直角三角形。若剩餘的面積為 350 平方公分，則截去的等腰直角三角形腰長為多少公分？',[r'\(\sqrt{5}\)',r'\(\dfrac{5}{2}\)',r'\(2\sqrt{5}\)','5'],4,r'設等腰直角三角形的腰長為 \(x\) 公分，\(20^2-4\times\dfrac{x^2}{2}=350\Rightarrow400-2x^2=350\Rightarrow x^2=25\Rightarrow x=\pm5\)（負不合）。',img=(25,890,735,995,840))
ch(r'如附圖，在 \(3\times3\) 的方格中，已知直行及橫列的總和均相等，則方格中 \(x\) 的值可能為何？',['1','2','3','4'],3,r'\(2x^2+1=x^2+(x+7)\)，\(x^2-x-6=0\)，\((x-3)(x+2)=0\)，\(x=3\) 或 \(-2\)，故選(C)。',img=(25,888,898,995,1002))
ch(r'詠晴將若干塊餅乾平分給朋友，當平分給 \(x\) 人時，每人恰可分得 12 塊；而當再多平分給 1 人時，每人可分得 \((x-2)\) 塊餅乾，且最後剩下 2 塊，則依題意可列出下列哪一個一元二次方程式？',[r'\(12x=(x-1)(x-2)+2\)',r'\(12x=(x+1)(x-2)+2\)',r'\(12x=(x-1)(x-2)-2\)',r'\(12x=(x+1)(x-2)-2\)'],2,r'當平分給 \((x+1)\) 人時，每人分得 \((x-2)\) 塊，且剩下 2 塊，\(12x=(x+1)(x-2)+2\)。')
ch('某飲料店調查某飲品每杯 120 元，每天可賣 200 杯，且將每杯售價提高 1 元，每天的銷售量會減少 5 杯。若昨日該飲品提高若干元後，共賣得 19500 元，則昨日該飲品每杯的售價為多少元？',['126','128','130','132'],3,r'設售價提高 \(x\) 元，\((120+x)(200-5x)=19500\Rightarrow5x^2+400x-4500=0\Rightarrow x^2+80x-900=0\Rightarrow(x-10)(x+90)=0\)，\(x=10\) 或 \(-90\)（不合），\(\therefore\) 所求＝\(120+10=130\)（元）。')
ch('【素養】附圖是小凱、阿翰兩人用相同的牙籤與一長方形紙片的長和寬比較長度後的對話：小凱：紙片的長比牙籤長的 2 倍長少 3 公分；阿翰：紙片的寬比牙籤長少 2 公分。若該長方形紙片的面積為 36 平方公分，則牙籤的長度為多少公分？',['6','8','9','12'],1,r'設牙籤長 \(x\) 公分，\((2x-3)(x-2)=36\Rightarrow2x^2-7x-30=0\Rightarrow(x-6)(2x+5)=0\Rightarrow x=6\) 或 \(-\dfrac{5}{2}\)（不合）。')
ch(r'【進階】坐標平面上有一點 \(P(-1,1)\)，若 \(A\)、\(B\) 兩點均在 \(x\) 軸上，且與 \(P\) 點的距離均為 \(\sqrt{10}\)，則 \(\overline{AB}=\)？',['4',r'\(2\sqrt{6}\)',r'\(4\sqrt{2}\)','6'],4,r'設點 \((m,0)\) 與 \(P\) 點距離為 \(\sqrt{10}\)，\([m-(-1)]^2+(0-1)^2=(\sqrt{10})^2\Rightarrow(m+1)^2=9\)，\(m+1=\pm3\)，\(m=2\) 或 \(-4\)，\(\therefore\overline{AB}=2-(-4)=6\)。')
endp()

sec('第14回 5-1 資料整理與統計圖表①')
ch('小程將班上 40 位學生的身高資料繪製成相對次數分配折線圖，且 145～150 公分這一組的學生有 6 位，則 145～150 公分這一組在圖中所標示的點坐標應為何？',['(147.5, 6)','(150, 6)','(147.5, 15)','(150, 15)'],3,r'\(\dfrac{6}{40}\times100\%=15\%\Rightarrow\) 點坐標應為 (147.5, 15)。')
ch('附圖是某次鋒面來襲，某地區 12 時～18 時累積降雨量的折線圖，則哪一個時段的降雨量最多？',['12 時～13 時','13 時～14 時','14 時～15 時','15 時～16 時'],2,r'13 時～14 時的降雨量為 \(7.1-2.8=4.3\)（mm），最多。',img=(27,762,465,1003,595))
ch('附圖為小靜班上學生身高的累積次數分配折線圖，則身高 145～155 公分的人數占全班人數的百分比為多少？',['25%','30%','35%','40%'],4,r'\(\dfrac{20-4}{40}\times100\%=40\%\)。',img=(27,770,598,1003,752))
ch(r'附表是某班學生體重的相對次數分配表的一部分（40～50 公斤：6 人、\(a\%\)；50～60 公斤：10 人、25%），則 \(a=\)？',['15','18','21','24'],1,r'全班人數＝\(10\div25\%=40\)（人），\(a=\dfrac{6}{40}\times100=15\)。',img=(27,770,758,1000,850))
psg('附圖是向陽社區居民 300 人年齡的累積相對次數分配折線圖。')
ch('則哪一組年齡的居民人數最多？',['10～20 歲','20～30 歲','30～40 歲','40～50 歲'],2,r'\(55\%-20\%=35\%\)，\(\therefore\) 20～30 歲的居民人數最多。',img=(27,775,872,1003,1010))
ch('未滿 20 歲的居民人數與 50 歲以上（含）的居民人數相差幾人？',['18','24','30','36'],2,r'\(300\times[20\%-(100\%-88\%)]=24\)（人）。',img=(27,775,872,1003,1010))
psg('附圖是甲、乙兩班學生喜愛球類的相對次數分配長條圖。若甲、乙兩班的學生數均為 40 人。')
ch('則甲、乙兩班學生喜愛籃球的人數相差幾人？',['2','4','8','10'],1,r'\(40\times(25\%-20\%)=2\)（人）。',img=(27,770,1082,1003,1235))
ch('甲、乙兩班中，喜愛哪一種球類的總人數最多？',['籃球','桌球','羽球','足球'],2,r'籃球：\(20\%+25\%=45\%\)；桌球：\(30\%+20\%=50\%\)，最多；羽球：\(15\%+25\%=40\%\)；足球：\(20\%+15\%=35\%\)。',img=(27,770,1082,1003,1235))
psg('附圖是籃球社社員一分鐘仰臥起坐測驗結果的相對次數分配直方圖。')
ch('若一分鐘做不到 30 下仰臥起坐的社員有 12 位，則籃球社共有幾位社員？',['20','40','60','80'],3,r'\(12\div(5\%+15\%)=60\)（位）。',img=(27,780,1285,1003,1438))
ch('【素養】承上題，小宇、蔡蔡是此籃球社的社員，兩人的對話如下。小宇：仰臥起坐次數和我在同一組的社員有 5 人；蔡蔡：我比你多做了 8 下。則蔡蔡最少做了幾下仰臥起坐？',['28','39','49','58'],4,r'小宇那一組共有 \(5+1=6\)（人），\(6\div60\times100\%=10\%\)，則小宇在 50～60 下這一組，\(\therefore\) 蔡蔡最少做了 \(50+8=58\)（下）。',img=(27,780,1285,1003,1438))
endp()

sec('第15回 5-1 資料整理與統計圖表②')
ch('附圖為八年忠班第一次段考數學科成績的累積次數分配折線圖，則成績未滿 60 分者占全班人數的百分比為何？',['9%','15%','18%','30%'],4,r'未滿 60 分者為 15 人，占全班的 \(\dfrac{15}{50}\times100\%=30\%\)。',img=(29,775,330,1003,458))
psg('附圖是投擲一顆公正骰子 100 次點數出現情形的相對次數分配長條圖。')
ch('則點數不到 4 點的次數占總投擲次數的百分比為何？',['45%','55%','60%','70%'],1,r'所求＝\(12\%+18\%+15\%=45\%\)。',img=(29,805,462,1000,595))
ch('出現次數最多與最少的兩筆資料相差了幾次？',['12','13','14','15'],4,r'4 點出現次數最多，6 點出現次數最少，\(\therefore\) 相差 \(100\times(25\%-10\%)=15\)（次）。',img=(29,805,462,1000,595))
psg(r'附表是八年甲班學生體重的次數及累積次數分配表：30～40 公斤 2 人（累積 2）；40～50 公斤 10 人（累積 \(a\)）；50～60 公斤 8 人（累積 20）；60～70 公斤 \(b\) 人；70～80 公斤 4 人（累積 \(c\)）；80～90 公斤 3 人（累積 \(d\)）。')
ch('已知 40～50 公斤這一組的相對次數為 25%，則全班學生有幾人？',['25','30','40','50'],3,r'\(10\div25\%=40\)（人）。',img=(29,705,655,975,895))
ch('下列何者錯誤？',[r'\(a=12\)',r'\(b=12\)',r'\(c=37\)',r'\(d=40\)'],2,r'\(a=2+10=12\)，\(b=40-20-4-3=13\)，\(c=20+13+4=37\)，\(d=40\)。',img=(29,705,655,975,895))
psg('附圖為排球社所有社員體重的次數分配直方圖，但 60～70 公斤的資料不慎被塗汙。')
ch('若 50～60 公斤這一組的相對次數為 40%，則排球社社員一共有幾人？',['19','20','21','22'],2,r'\(8\div40\%=20\)（人）。',img=(29,775,915,1000,1052))
ch('60～70 公斤的人數比 70～80 公斤的人數多幾人？',['1','2','3','4'],3,r'60～70 公斤有 \(20-4-8-2-1=5\)（人），所求＝\(5-2=3\)（人）。',img=(29,775,915,1000,1052))
psg('附圖是八年一班 50 位學生英語科週考成績的累積相對次數分配折線圖。')
ch('則 70 分以上（含）的學生有幾人？',['21','23','25','27'],2,r'\(100\%-54\%=46\%\)，\(50\times46\%=23\)（人）。',img=(29,778,1110,1003,1262))
ch('【素養】承上題，根據小非、阿振兩人的對話，判斷下列敘述何者正確？小非：中位數和我的成績在同一組！阿振：我的成績這一組人數是最多的！',['小非的成績較好','阿振的成績較好','小非的成績可能不到 60 分','阿振的成績可能為 80 分'],2,r'小非：\(36\%<50\%<54\%\)，即中位數在 60～70 分這一組；阿振：\(74\%-54\%=20\%\) 最多，即阿振成績在 70～80 分這一組，\(\therefore\) 阿振的成績較好。',img=(29,778,1110,1003,1262))
ch('【進階】附圖是某公司甲、乙兩個部門員工智商的相對次數分配折線圖，若甲部門有 30 人，乙部門有 20 人，則哪一個部門員工智商 110 以上（含）的人數較多？多幾人？',['甲部門較多，多 1 人','甲部門較多，多 2 人','乙部門較多，多 1 人','乙部門較多，多 2 人'],1,r'甲：\(30\times(10\%+20\%)=9\)（人）；乙：\(20\times(25\%+15\%)=8\)（人），\(\therefore\) 甲部門較多，多 \(9-8=1\) 人。',img=(29,760,1428,1003,1572))
endp()

sec('第16回 複習三（4-1～5-1）')
ch(r'若 \(2a^2-5a-1=0\)，則 \(a=\)？',[r'\(\dfrac{5\pm\sqrt{21}}{4}\)',r'\(\dfrac{5\pm\sqrt{23}}{4}\)',r'\(\dfrac{5\pm\sqrt{31}}{4}\)',r'\(\dfrac{5\pm\sqrt{33}}{4}\)'],4,r'\(a=\dfrac{-(-5)\pm\sqrt{(-5)^2-4\times2\times(-1)}}{2\times2}=\dfrac{5\pm\sqrt{25+8}}{4}=\dfrac{5\pm\sqrt{33}}{4}\)。')
ch('附表是八年一班同學跳遠成績的累積次數分配表（0～1.5 公尺：2；1.5～3：10；3～4.5：14；4.5～6：21；6～7.5：26），則人數最多的那一組有多少人？',['6','7','8','9'],3,r'0～1.5 公尺：2 人；1.5～3 公尺：\(10-2=8\)（人）；3～4.5 公尺：\(14-10=4\)（人）；4.5～6 公尺：\(21-14=7\)（人）；6～7.5 公尺：\(26-21=5\)（人）。',img=(31,585,445,978,502))
ch(r'若一元二次方程式 \(x^2+2x-360=0\) 的兩根為 \(a\)、\(b\)，且 \(a>b\)，則 \(2a+b=\)？',['4','12','16','22'],3,r'\(x^2+2x+1=360+1\Rightarrow(x+1)^2=361\Rightarrow x+1=\pm19\)，\(x=18\) 或 \(-20\Rightarrow a=18\)，\(b=-20\)，\(2a+b=36-20=16\)。')
ch('附圖是某班學生體重的相對次數分配直方圖，若 40～45 公斤的有 6 人，則 50 公斤以上（含）的有多少人？',['12','18','20','24'],2,r'全班人數＝\(6\div15\%=40\)（人），所求＝\(40\times(25\%+10\%+10\%)=18\)（人）。',img=(31,775,722,985,868))
ch('下列哪一個一元二次方程式無解？',[r'\(x^2-5x+3=0\)',r'\(2x^2+4x+2=0\)',r'\(9x=4x^2+6\)',r'\(x(x-1)=0\)'],3,r'(A) 判別式＝\((-5)^2-4\times1\times3=13>0\)；(B) 判別式＝\(4^2-4\times2\times2=0\)；(C) 原式 \(\Rightarrow4x^2-9x+6=0\)，判別式＝\((-9)^2-4\times4\times6=-15<0\)；(D) 兩根為 0 和 1，故選(C)。')
ch(r'【素養】如附圖，有塊長方形土地面積為 1200 平方公尺，中間開闢一個長 30 公尺、寬 20 公尺的長方形花園，且花園四周為等寬的走道，寬度為 \(x\) 公尺，則下列有關 \(x\) 的關係式何者正確？',[r'\((30+x)(20+x)=1200\)',r'\((30+2x)(20+2x)=1200\)',r'\(2(20x+30x)=1200-30\times20\)',r'\(2(20x+2x)(30x+2x)=1200+30\times20\)'],2,r'土地的長為 \((30+2x)\) 公尺、寬為 \((20+2x)\) 公尺，\((30+2x)(20+2x)=1200\)。',img=(31,828,1005,1008,1118))
ch('某校學生共有 1152 人，且每班的人數均相等。若每班人數加上 4 恰好為全校的班級數，則每班學生有幾人？',['30','32','34','36'],2,r'設每班有 \(x\) 人，則班級數為 \(x+4\)，\(x(x+4)=1152\)，\(x^2+4x+4=1152+4\)，\((x+2)^2=1156=34^2\)，\(x+2=\pm34\)，\(x=32\) 或 \(-36\)（不合）。')
ch(r'若 \(a\) 為方程式 \(x^2-4x-7=0\) 的一根，則 \((a-1)(a-3)\) 的值為何？',['10','13','15','17'],1,r'\(a^2-4a-7=0\)，\(a^2-4a=7\)，\(\therefore(a-1)(a-3)=a^2-4a+3=7+3=10\)。')
ch(r'已知甲、乙兩數的和為 5，乘積為 \(\dfrac{44}{9}\)，則 \(|\) 甲數－乙數 \(|=\)？',[r'\(\dfrac{7}{3}\)','3',r'\(\dfrac{10}{3}\)','4'],1,r'設兩數為 \(x\)、\(5-x\)，\(x(5-x)=\dfrac{44}{9}\)，\(9x^2-45x+44=0\)，\((3x-4)(3x-11)=0\)，\(x=\dfrac{4}{3}\) 或 \(\dfrac{11}{3}\)，\(5-x=\dfrac{11}{3}\) 或 \(\dfrac{4}{3}\)，所求＝\(\left|\dfrac{11}{3}-\dfrac{4}{3}\right|=\dfrac{7}{3}\)。')
ch(r'已知 \(x=\dfrac{-3-2\sqrt{3}}{2}\) 是 \(x^2+ax+b=0\) 的一根，則 \(a+b=\)？',['1',r'\(\dfrac{3}{2}\)','2',r'\(\dfrac{9}{4}\)'],4,r'\(x=\dfrac{-3-2\sqrt{3}}{2}\Rightarrow2x+3=-2\sqrt{3}\)，\((2x+3)^2=(-2\sqrt{3})^2\)，\(4x^2+12x+9=12\)，\(4x^2+12x-3=0\)，\(x^2+3x-\dfrac{3}{4}=0\Rightarrow a=3\)，\(b=-\dfrac{3}{4}\)，\(a+b=\dfrac{9}{4}\)。')
endp()
